"use client";

import React, { useState } from "react";
import { Share2, Link, Check } from "lucide-react";

export function BlogShareButtons() {
  const [copied, setCopied] = useState(false);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-xl shadow-lg select-none font-sans text-foreground flex items-center justify-between">
      <span className="text-xs font-bold text-muted-foreground flex items-center gap-1"><Share2 className="w-4 h-4 text-violet-400" /> Share Article</span>
      <div className="flex gap-2">
        <button 
          onClick={() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 1500);
          }}
          className="p-1.5 bg-secondary hover:bg-secondary/60 border border-border rounded-lg text-xs flex items-center gap-1"
        >
          {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Link className="w-3.5 h-3.5" />}
          <span>{copied ? "Copied" : "Copy Link"}</span>
        </button>
      </div>
    </div>
  );
}
